/* Local-only matching UI. No matching results or applicant drafts are persisted. */
const matchState={workerId:null,days:0,level:'',openOrderId:null,tab:'jobs',query:'',pickerOpen:false,phoneShown:false,profileOpen:false,excludedOpen:false,cache:new Map(),calculations:0,lastRenderKey:''};
let matchViewRequest=0,matchSearchTimer=null;
const matchWorkerFields=['id','name','gender','birthDate','age','desiredJob1','desiredJob2','desiredJob3','desiredJob','cantonese','mandarin','english','otherLanguages','workHistory','workedHongKong','hkEmployer','hkExitDate','certificates','skills','desiredSalary','height','weight','education','health','hometown','marital','phone','photo','educationHistory','hobbies','matchProfile'];
const matchOrderFields=['id','code','title','employer','gender','age','language','salary','workContent','requirements','notes','createdAt','matchProfile'];
const matchMarks=ZYMatching.marks,matchLevelLabels={high:'高',mid:'中',low:'低'},matchDots={high:'●●●',mid:'●●○',low:'●○○'};
const matchCopyFields=(value,keys)=>Object.fromEntries(keys.map(k=>[k,value[k]]));
const selectedMatchWorker=()=>workers.find(w=>w.id===matchState.workerId);
function canEditMatchWorker(){return ['admin','staff'].includes(sessionUser?.role)&&!sessionUser?.readOnly}
function matchValue(value){return String(value??'').trim()}
function matchPhone(worker){const phone=matchValue(worker.phone);return phone?'****'+phone.replace(/\D/g,'').slice(-4):''}
function matchAgeText(worker){const age=ZYMatching.workerAge(worker);return age===null?'':age+'岁'}
function matchWorkerLabel(worker){return [worker.name,worker.gender,matchAgeText(worker)].filter(Boolean).join(' · ')}
function matchReason(reason){if(/期望薪资缺失|无法解析|未作汇率换算/.test(reason.template||reason.text))reason={template:selectedMatchWorker()?.desiredSalary?'期望薪金待核对':'劳工未填期望薪金',values:{},text:selectedMatchWorker()?.desiredSalary?'期望薪金待核对':'劳工未填期望薪金'};return `<span data-match-reason data-user-content data-template="${esc(reason.template)}" data-values="${esc(JSON.stringify(reason.values||{}))}">${esc(reason.text)}</span>`}
function matchGeneratedValue(template,key,value){
 if(ZYI18n.language!=='en')return String(value??'');const raw=String(value??'');
 if(template==='要求{required}，劳工为{actual}')return raw==='男性'?'male':raw==='女性'?'female':raw;
 if(key==='major'||key==='jobMajor')return ZYI18n.translate(raw);if(key==='workerMajors')return raw.split('、').map(x=>ZYI18n.translate(x)).join(' / ');
 if(key==='gap')return raw==='达到要求'?'meets requirement':raw.replace(/^差(\d+)级$/,'$1 level(s) below');
 if(key==='duration')return raw==='时长不明，按12个月'?'unknown duration; 12 months assumed':raw.replace(/^约/,'approx. ').replace(/(\d+)年(\d+)个月/,'$1 years $2 months');
 if(key==='end')return raw==='至今'?'current':raw==='结束时间不明'?'end date unknown':raw.replace(/(\d+)年离职/,'left in $1');
 return raw==='未填写'?'not provided':raw;
}
function localiseMatchReasons(){
 document.querySelectorAll('[data-match-reason]').forEach(node=>{
  const signature=ZYI18n.language+'|'+node.dataset.template+'|'+node.dataset.values;if(node.dataset.localized===signature)return;
  const values=JSON.parse(node.dataset.values||'{}'),template=node.dataset.template,text=ZYI18n.translate(template).replace(/\{n\} (orders|days)/g,(part,word)=>Number(values.n)===1?'{n} '+word.slice(0,-1):part),pieces=text.split(/(\{\w+\})/g);
  node.innerHTML=pieces.map(piece=>/^\{\w+\}$/.test(piece)?`<span data-user-content>${esc(matchGeneratedValue(template,piece.slice(1,-1),values[piece.slice(1,-1)]))}</span>`:esc(piece)).join('');node.dataset.localized=signature;
 });document.querySelectorAll('.match-explanation').forEach(el=>{if(el.title!==el.textContent)el.title=el.textContent});
}
function openWorkerMatch(id){const previous={workerId:matchState.workerId,phoneShown:matchState.phoneShown,openOrderId:matchState.openOrderId,level:matchState.level,tab:matchState.tab};matchState.workerId=id||null;matchState.phoneShown=false;matchState.openOrderId=null;matchState.level='';matchState.tab='jobs';if(go('match')===false){Object.assign(matchState,previous);return false}}
function workerSavedToast(id){toast('劳工资料已保存');const link=document.createElement('button');link.type='button';link.textContent='去匹配岗位';link.onclick=()=>openWorkerMatch(id);$('.toast')?.append(' ',link)}
async function matchView({load=true,sync=false}={}){
 const request=++matchViewRequest,userId=sessionUser?.id;
 if(load){if(!$('#match-workspace'))$('#content').innerHTML='<p role="status">正在读取劳工资料…</p>';try{await loadWorkers();await loadJobTaxonomy()}catch{if(view==='match'&&sessionUser?.id===userId)$('#content').innerHTML='<p>劳工资料读取失败，请重试</p><button onclick="matchView()">重试</button>';return}}
 if(view!=='match'||sessionUser?.id!==userId||request!==matchViewRequest)return;
 if(matchState.workerId&&!selectedMatchWorker()){matchState.workerId=null;matchState.openOrderId=null;matchState.phoneShown=false;matchState.cache.clear();toast('所选劳工已被删除')}
 renderMatchPage({sync});
}
function matchBundle(){
 const selected=selectedMatchWorker();if(!selected)return {key:'empty|'+JSON.stringify(workers.map(w=>[w.id,w.name,matchPhone(w)])),results:[],orders:new Map()};
 const worker=matchCopyFields(selected,matchWorkerFields),key=JSON.stringify(worker)+'|'+revision+'|'+matchState.days+'|'+ZYTime.todayKey()+'|'+ZYClassification.revision;
 if(matchState.cache.has(key))return matchState.cache.get(key);
 const ready=orders.filter(o=>orderState(o)==='ready').map(o=>matchCopyFields(orderPublication(o).order,matchOrderFields));
 const results=ZYMatching.matchWorker(worker,ready,{days:matchState.days,today:ZYTime.todayKey()}),bundle={key,results,orders:new Map(ready.map(o=>[o.id,o]))};
 matchState.calculations++;matchState.cache.set(key,bundle);if(matchState.cache.size>8)matchState.cache.delete(matchState.cache.keys().next().value);return bundle;
}
function matchAIStatus(bundle){
 if(!window.ZYAIMatching)return '';const state=ZYAIMatching.state(bundle.key);let text='AI 分析中，已分析 '+(state?.done||0)+' / 共 '+(state?.total??bundle.results.length)+' 张',kind='info';
 if(state?.status==='failed'){text='AI 暂时不可用，下面是规则结果';kind='warning'}
 if(state?.status==='ready')text='AI 分析于 '+ZYTime.formatDateTime(state.completedAt).slice(11);
 return `<div class="zy-notice zy-notice--${kind} ai-match-status" role="${kind==='warning'?'alert':'status'}">${esc(text)}</div>`;
}
function matchDirectory(){const ready=orders.filter(o=>orderState(o)==='ready').map(o=>orderPublication(o).order);const highCount=worker=>ZYMatching.matchWorker(worker,ready,{today:ZYTime.todayKey(),days:matchState.days}).filter(r=>!r.excluded&&!r.manual&&r.level==='high').length;return `<section class="panel"><h2 class="match-empty-title">选择劳工开始匹配</h2><div class="worker-directory">${workers.map(w=>`<button onclick="selectMatchWorker(${jsValue(w.id)})"><span data-user-content>${esc(matchWorkerLabel(w))}</span><span data-user-content>${esc(w.desiredJob1||w.desiredJob||'')}</span><span class="muted">规则高匹配 <b data-user-content>${highCount(w)}</b> →</span></button>`).join('')}</div></section>`}
function matchExcluded(excluded,bundle){
 const groups=new Map();for(const result of excluded){const reason=result.reasonDetails?.[0]?.text||result.reasons?.[0]||'',name=/性别|男性|女性/.test(reason)?'性别不符':/年龄|岁/.test(reason)?'年龄超出':/经历/.test(reason)?'经历不相关':'其他条件';if(!groups.has(name))groups.set(name,[]);groups.get(name).push(result)}
 return `<details class="match-excluded" ${matchState.excludedOpen?'open':''} ontoggle="if(this.isConnected)matchState.excludedOpen=this.open"><summary>另有 <span data-user-content>${excluded.length}</span> 张不符合</summary>${[...groups].map(([name,rows])=>`<details class="match-excluded-group"><summary>${name} <span data-user-content>${rows.length}</span> 张</summary>${rows.map(r=>{const o=bundle.orders.get(r.orderId);return `<p class="match-excluded-row"><span data-user-content>${esc(o.title)} · ${esc(o.salary)}</span> · ${r.reasonDetails.map(matchReason).join('；')}</p>`}).join('')}</details>`).join('')}</details>`;
}
function renderMatchPage({sync=false}={}){
 const baseBundle=matchBundle(),selected=selectedMatchWorker(),bundle=window.ZYAIMatching&&selected?ZYAIMatching.decorate(baseBundle,selected):baseBundle;
 const renderKey=bundle.key+'|'+(window.ZYAIMatching?JSON.stringify([ZYAIMatching.state(bundle.key)?.status,ZYAIMatching.state(bundle.key)?.done]):'');
 if(sync&&$('#match-workspace')&&renderKey===matchState.lastRenderKey){if(matchState.pickerOpen)renderWorkerChoices();return}
 const focused=document.activeElement?.id,searchValue=$('#match-worker-search')?.value,scrollYBefore=scrollY,profileScroll=$('#match-profile-body')?.scrollTop||0;
 const matching=bundle.results.filter(r=>!r.excluded&&!r.manual),manual=bundle.results.filter(r=>r.manual),excluded=bundle.results.filter(r=>r.excluded),open=matching.find(r=>r.orderId===matchState.openOrderId);
 if(matchState.openOrderId&&!open)matchState.openOrderId=null;
 const rangeOptions=[0,7,14,30].map(days=>`<option value="${days}" ${matchState.days===days?'selected':''}>${days?'最近'+days+'天':'全部日期'}</option>`).join('');
 const filters=`<div class="match-filter"><select class="match-range-mobile" aria-label="公司单日期范围" onchange="setMatchRange(Number(this.value))">${rangeOptions}</select><div class="match-chips">${[['','全部'],['high','高'],['mid','中'],['low','低'],['manual','需人工判断']].map(([level,label])=>`<button data-match-level="${level}" aria-pressed="${matchState.level===level}" onclick="setMatchLevel('${level}')">${label} <b data-user-content>${level==='manual'?manual.length:level?matching.filter(r=>r.level===level).length:matching.length+manual.length}</b></button>`).join('')}</div><small>共 <span data-user-content>${bundle.results.length}</span> 张可发布公司单</small></div>`;
 const rows=matching.length&&matchState.level!=='manual'?`<div class="match-table-scroll"><div class="match-table"><div class="match-grid match-table-head" aria-hidden="true"><span>匹配度</span><span>职位 · 雇主</span><span>月薪</span><span>匹配理由</span><span>操作</span></div>${['high','mid','low'].filter(level=>!matchState.level||matchState.level===level).map(level=>{const group=matching.filter(r=>r.level===level);return !group.length?'':`<section class="match-group match-${level}"><h2>${{high:'高匹配',mid:'中匹配',low:'低匹配'}[level]} <span data-user-content>${group.length}</span></h2>${group.map(result=>matchRow(result,bundle.orders.get(result.orderId))).join('')}</section>`}).join('')}</div></div>`:'';
 const manualRows=manual.length&&(!matchState.level||matchState.level==='manual')?`<section class="match-manual"><h2>需人工判断 <span data-user-content>${manual.length}</span></h2>${manual.map(r=>{const o=bundle.orders.get(r.orderId);return `<div class="match-manual-row"><b data-user-content>${esc(o.title)}</b><span data-user-content>${esc(o.salary)}</span><span>${r.reasonDetails.map(matchReason).join('；')}</span><button onclick="copyOrder(${jsValue(o.id)})">复制</button></div>`}).join('')}</section>`:'';
 const results=selected?`${matchAIStatus(bundle)}${filters}${rows}${manualRows}${!matching.length&&!manual.length?'<p class="note">没有符合的岗位</p>':''}${excluded.length?matchExcluded(excluded,bundle):''}<p class="match-rule-note">AI等级依据工作经历、可迁移技能和岗位条件；规则分仅供参考。性别、年龄仍为硬条件。</p>`:matchDirectory();
 $('#content').innerHTML=`<div id="match-workspace"><div class="match-toolbar"><h1>岗位匹配</h1><div class="match-picker"><input id="match-worker-search" role="combobox" aria-label="选择劳工，搜索姓名或电话后4位" aria-autocomplete="list" aria-expanded="${matchState.pickerOpen}" aria-controls="match-worker-options" autocomplete="off" placeholder="选择劳工，搜索姓名或电话后4位" value="${esc(matchState.pickerOpen?matchState.query:selected?matchWorkerLabel(selected):'')}" onfocus="showWorkerChoices()" oninput="queueWorkerChoices(this.value)" onkeydown="matchPickerKeys(event)">${selected?'<button class="match-picker-clear" aria-label="清除所选劳工" onclick="clearMatchWorker()">×</button>':''}<div id="match-worker-options" role="listbox" aria-label="已登记劳工" ${matchState.pickerOpen?'':'hidden'}></div></div><div class="match-range" role="group" aria-label="公司单范围">${[0,7,14,30].map(days=>`<button data-match-days="${days}" aria-pressed="${matchState.days===days}" onclick="setMatchRange(${days})">${days?'最近'+days+'天':'全部'}</button>`).join('')}</div></div>${!workers.length?'<div class="panel empty">还没有已登记的劳工<div class="actions"><button class="primary" onclick="go(\'workers\')">去劳工登记</button></div></div>':`${selected?`<div class="match-mobile-tabs" role="tablist" aria-label="岗位匹配内容"><button role="tab" aria-selected="${matchState.tab==='jobs'}" onclick="setMatchTab('jobs')">匹配岗位 <span data-user-content>${matching.length+manual.length}</span></button><button role="tab" aria-selected="${matchState.tab==='profile'}" onclick="setMatchTab('profile')">劳工资料</button></div>`:''}<div class="match-columns" data-selected="${!!selected}" data-tab="${matchState.tab}"><section class="match-results" aria-label="匹配岗位">${results}</section>${selected?`<aside class="match-profile" aria-label="劳工资料">${matchProfile(selected,open,bundle)}</aside>`:''}</div>`}</div>`;
 matchState.lastRenderKey=renderKey;if(selected&&window.ZYAIMatching)void ZYAIMatching.start(selected,baseBundle);renderWorkerChoices();localiseMatchReasons();fitMatchProfile();
 if(sync){window.scrollTo(0,scrollYBefore);if($('#match-profile-body'))$('#match-profile-body').scrollTop=profileScroll;if(focused){matchState.restoringFocus=true;document.getElementById(focused)?.focus({preventScroll:true});matchState.restoringFocus=false;}if(focused==='match-worker-search'&&matchState.pickerOpen&&searchValue!==undefined)$('#match-worker-search').value=searchValue}
}
function matchRow(result,order){
 const id=jsValue(result.orderId),expanded=result.orderId===matchState.openOrderId;
 const dims=[{...result.experience,label:result.experience.relevance==='certificate'?'证书':'经历'},...result.conditions.items,{...result.intent,label:'意向',mark:result.intent.bonus?'bonus':'unknown'}],seen=new Set(),tags=dims.filter(d=>{if(seen.has(d.label))return false;seen.add(d.label);return true}).map(d=>`<span class="match-tag mark-${d.mark}">${esc(d.label)}${d.mark==='bonus'?'+':matchMarks[d.mark]}</span>`).join('');
 const reason=result.aiReason||result.experience.reasons?.[0]?.text||'按工作经历和岗位条件匹配';
 const bar=d=>`<div class="match-dimension"><b>${esc(d.label)}</b><span class="match-bar" aria-hidden="true"><i style="width:${d.got===null?0:100*d.got/d.max}%;background:${d.got/d.max>=.75?'var(--ready-dot)':d.got/d.max>=.4?'var(--brand)':'var(--match-bar-low)'}"></i></span><span class="numeric" data-user-content>${d.displayGot===null?'未填写':Math.round(d.displayGot)}/${d.max}</span><span class="match-tag mark-${d.mark}">${matchMarks[d.mark]}</span><span class="match-explanation" tabindex="0">${d.reasons.map(matchReason).join('；')}</span></div>`;
 return `<article class="match-entry ${expanded?'expanded':''}" data-match-order="${esc(result.orderId)}"><div class="match-grid match-row" onclick="matchRowClick(event,${id})"><span class="match-level level-${result.level}"><i aria-hidden="true">${matchDots[result.level]}</i> <span>${matchLevelLabels[result.level]}</span></span><button class="match-order-open" aria-expanded="${expanded}" onclick="toggleMatchOrder(${id})"><strong data-user-content title="${esc(order.title)}">${esc(order.title)}</strong>${order.employer?`<span class="match-employer" data-user-content title="${esc(order.employer)}">${esc(order.employer)}</span>`:''}</button><span class="match-salary" data-user-content title="${esc(order.salary)}">${esc(order.salary)}</span><div class="match-tags" data-user-content title="${esc(reason)}">${esc(reason)}</div><button class="primary match-copy" onclick="copyOrder(${id})">复制</button></div>${expanded?`<div class="match-breakdown"><p class="match-reason-detail" data-user-content>${esc(reason)}</p>${result.missing?.length?`<p class="zy-notice zy-notice--warning">缺少条件：<span data-user-content>${esc(result.missing.join('；'))}</span></p>`:''}${result.disagreement?'<p class="note">AI 与规则判断存在差异，建议人工确认。</p>':''}<div class="match-detail-tags">${tags}</div><p class="muted">规则参考分 <span data-user-content>${Math.round(result.ruleScore??result.score)}/100</span></p>${result.hardChecks.length?`<p class="note">${result.hardChecks.map(matchReason).join('；')}</p>`:''}${bar(result.experience)}<h3>岗位条件</h3>${result.conditions.items.length?result.conditions.items.map(c=>`<p class="match-condition"><span class="match-tag mark-${c.mark}">${matchMarks[c.mark]}</span> ${matchReason(c.reason)}</p>`).join(''):'<p>公司单未写其他条件</p>'}<h3>意向加分</h3><p><span data-user-content>+${result.intent.bonus}</span> ${result.intent.reasons.map(matchReason).join('；')}</p><button class="match-profile-link" onclick="setMatchTab('profile')">在劳工资料中查看</button></div>`:''}</article>`;
}

function matchProfile(worker,open,bundle){
 const small=matchMedia('(max-width:639px)').matches,desktop=matchMedia('(min-width:1100px)').matches,experience=open?.dims.find(d=>d.key==='experience'),language=open?.language,selectedHistory=experience?.histories||[],missing=[...new Set((open?[open]:bundle.results.filter(r=>!r.excluded&&!r.manual)).flatMap(r=>r.dims.flatMap(d=>d.missing||[])))];
 const labelValue=(label,value)=>value?`<dt>${label}</dt><dd data-user-content>${esc(value)}</dd>`:'';
 const allHistories=ZYMatching.histories(worker),photo=/^data:image\/(jpeg|png|webp);base64,/i.test(worker.photo||'')?`<img src="${esc(worker.photo)}" alt="劳工照片">`:`<span class="match-avatar" data-user-content>${esc(Array.from(worker.name||'—')[0])}</span>`;
 return `<${small||desktop?'section':'details'} ${small||desktop||matchState.profileOpen?'open':''} class="match-profile-shell" ontoggle="if(this.isConnected&&matchMedia('(min-width:640px) and (max-width:1099px)').matches)matchState.profileOpen=this.open"><summary><span data-user-content>${esc([matchWorkerLabel(worker),worker.desiredJob1||worker.desiredJob].filter(Boolean).join(' · '))}</span></summary><div class="match-profile-body" id="match-profile-body" tabindex="-1"><div class="match-person">${photo}<div><h2 data-user-content>${esc(worker.name)}</h2>${window.ZYAIMatching?'<button class="match-reanalyze" onclick="ZYAIMatching.start(selectedMatchWorker(),matchBundle(),{force:true})">重新 AI 分析</button>':''}<p class="match-person-summary" data-user-content title="${esc([worker.gender,matchAgeText(worker),worker.hometown,worker.health,worker.education].filter(Boolean).join(' · '))}">${esc([worker.gender,matchAgeText(worker),worker.hometown,worker.health,worker.education].filter(Boolean).join(' · '))}</p></div></div>${window.ZYAIMatching&&ZYAIMatching.state(bundle.key)?.profile?`<section class="ai-worker-summary"><h3>AI劳工画像</h3><p data-user-content>${esc(ZYAIMatching.state(bundle.key).profile.summary)}</p><p data-user-content>${esc(ZYAIMatching.state(bundle.key).profile.directions.map(d=>d.name+' · '+d.years+'年').join('；'))}</p></section>`:''}${worker.phone?`<p class="match-phone"><span>联系电话</span> <span data-user-content>${esc(matchState.phoneShown?worker.phone:matchPhone(worker))||'—'}</span>${worker.phone?`<button aria-pressed="${matchState.phoneShown}" onclick="toggleMatchPhone()">${matchState.phoneShown?'隐藏':'显示'}</button>`:''}</p>`:''}<h3>求职意向</h3><div class="match-intents">${[worker.desiredJob1||worker.desiredJob,worker.desiredJob2,worker.desiredJob3].map((intent,i)=>intent?`<span class="match-intent ${open?.matchedIntentIndex===i?'matched':''}" data-intent-index="${i}"><span data-user-content>${i+1} · ${esc(intent)}</span></span>`:'').join('')}</div>${worker.desiredSalary?`<p><span>期望薪金</span> <span data-user-content>${esc(worker.desiredSalary)}</span></p>`:''}<h3>语言能力</h3>${[['cantonese','粤语'],['mandarin','普通话'],['english','英语']].map(([key,label])=>{const level=ZYMatching.languageLevel(worker[key]);return !worker[key]?'':`<div class="match-language ${language?.satisfiedLanguages.includes(key)?'matched':''}" data-language-key="${key}"><span>${label}</span><span class="match-language-bars" aria-hidden="true">${Array.from({length:5},(_,i)=>`<i class="${level!==null&&i<Math.round(level/4*5)?'filled':''}"></i>`).join('')}</span><b data-user-content>${esc(worker[key])||'—'}</b></div>`}).join('')}${worker.otherLanguages?`<p><span>其他语言</span> <span data-user-content>${esc(worker.otherLanguages)}</span></p>`:''}<h3>工作经历</h3>${allHistories.length?allHistories.map(h=>{const used=selectedHistory.find(r=>r.index===h.index),unclassified=ZYMatching.profileFor(worker,'worker').history.find(r=>r.index===h.index)?.major==='other';return `<div class="match-history ${used?'matched':''}" data-history-index="${h.index}"><div><strong data-user-content>${esc(h.position||'')}</strong> <span data-user-content>${esc(h.employer||'')}</span><time data-user-content>${esc(h.period||'')}</time></div><p data-user-content title="${esc(h.duties||'')}">${esc(h.duties||'')}</p><p class="match-classification">${unclassified?'<span class="badge draft">未归类</span><small>此经历暂未计分，其他已归类经历和证书照常匹配。</small>':classificationLabel(ZYMatching.profileFor(worker,'worker').history.find(r=>r.index===h.index))}</p>${!h.duties?'<small>补充工作内容可以让匹配更准确</small>':''}${used?`<small>${matchReason({template:'与当前岗位相关 · {duration}',values:{duration:used.periodInfo.unknown?'时长不明，按12个月':Math.floor(used.periodInfo.months/12)+'年'+used.periodInfo.months%12+'个月'},text:'与当前岗位相关'})}</small>`:''}</div>`}).join(''):'<p>未填写工作经历</p>'}${[worker.workedHongKong,worker.hkEmployer,worker.hkExitDate,worker.certificates,worker.skills,worker.education,worker.height,worker.weight,worker.hobbies].some(Boolean)?'<h3>其他资料</h3>':''}<dl class="match-worker-details">${labelValue('香港劳务经历',worker.workedHongKong)}${labelValue('香港雇主',worker.hkEmployer)}${labelValue('离港日期',worker.hkExitDate)}${labelValue('专业证书',worker.certificates||worker.skills)}${labelValue('最高学历',worker.education)}${labelValue('身高',worker.height)}${labelValue('体重',worker.weight)}${labelValue('特长爱好',worker.hobbies)}</dl>${ZYMatching.profileFor(worker,'worker').certificates.map(c=>`<p class="match-classification"><span data-user-content>${esc(c.evidence)}</span> → ${classificationLabel(c)}</p>`).join('')}${worker.educationHistory?.length?'<h3>教育经历</h3>':''}${(worker.educationHistory||[]).map(h=>`<p data-user-content>${esc([h.period,h.school,h.major,h.qualification].filter(Boolean).join(' · '))}</p>`).join('')}${missing.length?`<div class="match-missing"><span>资料不全：${missing.map(label=>`<span>${esc(label)}</span>`).join('、')}</span></div>`:''}</div><div class="match-profile-actions">${canEditMatchWorker()?`<button onclick="editWorker(${jsValue(worker.id)})">编辑资料</button>`:''}<button onclick="previewMatchWorker()">预览登记表</button></div></${small||desktop?'section':'details'}>`;
}
function fitMatchProfile(){const profile=$('.match-profile');if(view!=='match'||!profile||!matchMedia('(min-width:1100px)').matches)return;profile.style.setProperty('--match-profile-height',Math.max(160,innerHeight-Math.max(20,profile.getBoundingClientRect().top)-20)+'px')}
addEventListener('resize',fitMatchProfile);
function matchRowClick(event,id){if(matchMedia('(max-width:639px)').matches&&!event.target.closest('button'))toggleMatchOrder(id)}
function previewMatchWorker(){const selected=selectedMatchWorker();if(!selected)return;const preview=matchCopyFields(selected,matchWorkerFields);preview.phone=matchState.phoneShown?selected.phone:matchPhone(selected);preview.age=String(ZYMatching.workerAge(selected)??'');if(!/^data:image\/(jpeg|png|webp);base64,/i.test(preview.photo||''))delete preview.photo;previewWorker(preview)}
function setMatchRange(days){matchState.days=days;matchState.openOrderId=null;matchState.excludedOpen=false;renderMatchPage()}
function setMatchLevel(level){matchState.level=level;matchState.openOrderId=null;renderMatchPage()}
function toggleMatchOrder(id){matchState.openOrderId=matchState.openOrderId===id?null:id;renderMatchPage();if(!matchMedia('(max-width:639px)').matches){const el=[...document.querySelectorAll('.match-entry')].find(e=>e.dataset.matchOrder===id);el?.querySelector('.match-order-open')?.focus({preventScroll:true})}}
function setMatchTab(tab){matchState.tab=tab;renderMatchPage();if(tab==='profile')$('#match-profile-body')?.focus({preventScroll:true});else $('.match-mobile-tabs button[aria-selected="true"]')?.focus({preventScroll:true})}
function toggleMatchPhone(){matchState.phoneShown=!matchState.phoneShown;renderMatchPage();$('.match-phone button')?.focus({preventScroll:true})}
function showWorkerChoices(){if(matchState.restoringFocus)return;matchState.pickerOpen=true;$('#match-worker-options').hidden=false;$('#match-worker-search').setAttribute('aria-expanded','true');renderWorkerChoices()}
function queueWorkerChoices(value){matchState.query=value;clearTimeout(matchSearchTimer);matchSearchTimer=setTimeout(()=>{if(view==='match')renderWorkerChoices()},200)}
function renderWorkerChoices(){
 const box=$('#match-worker-options');if(!box)return;box.hidden=!matchState.pickerOpen;if(!matchState.pickerOpen)return;
 const q=matchState.query.trim().toLowerCase(),list=workers.filter(w=>matchValue(w.name).toLowerCase().includes(q)||/^\d{1,4}$/.test(q)&&matchValue(w.phone).replace(/\D/g,'').slice(-4).includes(q));
 box.innerHTML='<div class="match-picker-count">共 '+list.length+' 人</div>'+list.map(w=>`<button role="option" aria-selected="${w.id===matchState.workerId}" data-match-worker="${esc(w.id)}" onclick="selectMatchWorker(${jsValue(w.id)})" data-user-content>${esc([matchWorkerLabel(w),w.desiredJob1||w.desiredJob,matchPhone(w)].filter(Boolean).join(' · '))}</button>`).join('')+(list.length?'':'<p>没有找到劳工</p>');
}
function selectMatchWorker(id){matchState.workerId=id;matchState.pickerOpen=false;matchState.query='';matchState.phoneShown=false;matchState.openOrderId=null;matchState.level='';matchState.tab='jobs';renderMatchPage();$('#match-worker-search')?.focus({preventScroll:true});matchState.pickerOpen=false;$('#match-worker-options').hidden=true;$('#match-worker-search').setAttribute('aria-expanded','false')}
function clearMatchWorker(){matchState.workerId=null;matchState.pickerOpen=false;matchState.query='';renderMatchPage()}
function matchPickerKeys(event){const box=$('#match-worker-options'),items=[...box.querySelectorAll('button')];if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();showWorkerChoices();const options=[...box.querySelectorAll('button')];options[event.key==='ArrowDown'?0:options.length-1]?.focus()}if(event.key==='Escape'){matchState.pickerOpen=false;box.hidden=true;event.target.setAttribute('aria-expanded','false')}}
addEventListener('keydown',event=>{if(!event.target.closest('#match-worker-options'))return;const items=[...$('#match-worker-options').querySelectorAll('button')],at=items.indexOf(document.activeElement);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();items[(at+(event.key==='ArrowDown'?1:items.length-1))%items.length]?.focus()}if(event.key==='Escape'){event.preventDefault();matchState.pickerOpen=false;$('#match-worker-options').hidden=true;$('#match-worker-search').focus();matchState.pickerOpen=false;$('#match-worker-options').hidden=true;$('#match-worker-search').setAttribute('aria-expanded','false')}});
addEventListener('click',event=>{if(view==='match'&&!event.target.closest('.match-picker')){matchState.pickerOpen=false;$('#match-worker-options')?.setAttribute('hidden','');$('#match-worker-search')?.setAttribute('aria-expanded','false')}});
for(const query of ['(max-width:639px)','(min-width:1100px)'])matchMedia(query).addEventListener('change',()=>{if(view==='match'&&$('#match-workspace'))renderMatchPage()});
window.ZYMatchUI={localise:localiseMatchReasons,leave(){matchState.phoneShown=false;matchState.pickerOpen=false},reset(){matchViewRequest++;clearTimeout(matchSearchTimer);Object.assign(matchState,{workerId:null,days:0,level:'',openOrderId:null,tab:'jobs',phoneShown:false,pickerOpen:false,query:'',profileOpen:false,excludedOpen:false,lastRenderKey:''});matchState.cache.clear();$('#match-workspace')?.remove()}};

async function reanalyzeMatchWorker(){const w=selectedMatchWorker();if(!w||!canEditMatchWorker())return;if(window.ZYAIMatching){await ZYAIMatching.saved(w.id);await matchView()}}
async function reanalyzeMatchOrder(){if(!canEditMatchWorker())return;await loadJobTaxonomy(true);renderMatchPage()}

function classificationLabel(c){if(!c)return '';return `<span>${esc(ZYClassification.majorLabel(c.major))}</span>${c.name?` · <span data-user-content>${esc(c.name)}</span>`:''}${c.by==='ai'?' <span data-user-content>AI</span>':''}`}
